import java.util.*; abstract class Vehicle08{int h;Vehicle08(int h){this.h=Math.max(0,h);}abstract double fee();} class Bike08 extends Vehicle08{Bike08(int h){super(h);}double fee(){return 10.0*h;}} class Car08 extends Vehicle08{Car08(int h){super(h);}double fee(){return h==0?0:30+20.0*(h-1);}} class Truck08 extends Vehicle08{Truck08(int h){super(h);}double fee(){return Math.max(100,50.0*h);}} public class Week08Problem02{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();int h=s.nextInt();Vehicle08 v=t.equals("BIKE")?new Bike08(h):t.equals("CAR")?new Car08(h):new Truck08(h);System.out.printf("%s: %.2f%n",t,v.fee());total+=v.fee();}System.out.printf("Total: %.2f%n",total);}}